// SLOW: per-key search with no memoisation of visited states (exponential). Generated by mk_wrongs.py.
/* Reference: linearizability checker for KV histories (task 168, variant c).
 * Per-key Wing-Gong-Lowe search, memoised on (linearized-set, value). */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF INT64_MAX
enum { GET, PUT, DEL, CAS };

typedef struct {
    int64_t call, ret;
    int kind, key;
    int64_t a, b, res; /* res: GET value (0 = NIL) / CAS 1=OK 0=FAIL */
} Op;

static char *buf;
static size_t blen, bpos;

static int tok(char **s, size_t *n) {
    while (bpos < blen && (buf[bpos] == ' ' || buf[bpos] == '\n' || buf[bpos] == '\r')) bpos++;
    if (bpos >= blen) return 0;
    *s = buf + bpos;
    size_t st = bpos;
    while (bpos < blen && buf[bpos] != ' ' && buf[bpos] != '\n' && buf[bpos] != '\r') bpos++;
    *n = bpos - st;
    return 1;
}
static int64_t num(void) {
    char *s; size_t n; tok(&s, &n);
    int64_t v = 0;
    for (size_t i = 0; i < n; i++) v = v * 10 + (s[i] - '0');
    return v;
}

static int cmp_key(const void *x, const void *y) {
    const Op *a = x, *b = y;
    return (a->key > b->key) - (a->key < b->key);
}
static int cmp_ret(const void *x, const void *y) {
    const Op *a = x, *b = y;
    return (a->ret > b->ret) - (a->ret < b->ret);
}
static Op *g_ops;
static int cmp_call_idx(const void *x, const void *y) {
    int64_t a = g_ops[*(const int *)x].call, b = g_ops[*(const int *)y].call;
    return (a > b) - (a < b);
}

/* ---- memo: open-addressing hash set over states (W words + value) ---- */
static int W;               /* words per bitset */
static uint64_t *arena;     /* state i at arena[i*(W+1)] : W words then value */
static size_t nstates, cap_states;
static int64_t *table;      /* -1 empty, else state index */
static size_t tmask;

static uint64_t hash_state(const uint64_t *s) {
    uint64_t h = 0x9E3779B97F4A7C15ULL;
    for (int i = 0; i <= W; i++) { h ^= s[i]; h *= 0xff51afd7ed558ccdULL; h ^= h >> 32; }
    return h;
}
static void grow_table(void);
/* returns index of state, inserting if new; *fresh set if inserted */
static size_t intern(const uint64_t *s, int *fresh) {
    if ((nstates + 1) * 2 > tmask + 1) grow_table();
    size_t h = hash_state(s) & tmask;
    while (table[h] >= 0) {
        if (memcmp(arena + (size_t)table[h] * (W + 1), s, sizeof(uint64_t) * (W + 1)) == 0) {
            *fresh = 0;
            return (size_t)table[h];
        }
        h = (h + 1) & tmask;
    }
    if (nstates == cap_states) {
        cap_states *= 2;
        arena = realloc(arena, cap_states * (W + 1) * sizeof(uint64_t));
    }
    memcpy(arena + nstates * (W + 1), s, sizeof(uint64_t) * (W + 1));
    table[h] = (int64_t)nstates;
    *fresh = 1;
    return nstates++;
}
static void grow_table(void) {
    size_t nsize = (tmask + 1) * 2;
    free(table);
    table = malloc(nsize * sizeof(int64_t));
    for (size_t i = 0; i < nsize; i++) table[i] = -1;
    tmask = nsize - 1;
    for (size_t k = 0; k < nstates; k++) {
        size_t h = hash_state(arena + k * (W + 1)) & tmask;
        while (table[h] >= 0) h = (h + 1) & tmask;
        table[h] = (int64_t)k;
    }
}

static int check_key(Op *ops, int n) {
    /* completed ops first (by ret), pending after */
    int m = 0;
    for (int i = 0; i < n; i++)
        if (ops[i].ret != INF) { Op t = ops[m]; ops[m] = ops[i]; ops[i] = t; m++; }
    if (m == 0) return 1;
    qsort(ops, (size_t)m, sizeof(Op), cmp_ret);
    int *by_call = malloc(sizeof(int) * (size_t)n);
    for (int i = 0; i < n; i++) by_call[i] = i;
    g_ops = ops;
    qsort(by_call, (size_t)n, sizeof(int), cmp_call_idx);

    W = (n + 63) / 64;
    nstates = 0;
    cap_states = 1024;
    arena = malloc(cap_states * (W + 1) * sizeof(uint64_t));
    tmask = 1023;
    table = malloc((tmask + 1) * sizeof(int64_t));
    for (size_t i = 0; i <= tmask; i++) table[i] = -1;
    size_t *stack = malloc(sizeof(size_t) * 1024), sp = 0, scap = 1024;
    uint64_t *cur = calloc((size_t)W + 1, sizeof(uint64_t));
    int fresh, ok = 0;
    stack[sp++] = intern(cur, &fresh);

    while (sp) {
        size_t si = stack[--sp];
        memcpy(cur, arena + si * (W + 1), sizeof(uint64_t) * (W + 1));
        /* first completed op not yet linearized */
        int low = -1;
        for (int w = 0; w < W; w++) {
            uint64_t z = ~cur[w];
            if (z) { low = w * 64 + __builtin_ctzll(z); break; }
        }
        if (low < 0 || low >= m) { ok = 1; break; }
        int64_t minret = ops[low].ret;
        int64_t val = (int64_t)cur[W];
        for (int j = 0; j < n; j++) {
            int i = by_call[j];
            if (ops[i].call > minret) break;
            if (cur[i / 64] >> (i % 64) & 1) continue;
            Op *o = &ops[i];
            int64_t nv;
            if (o->kind == GET) {
                if (o->res != val) continue;
                nv = val;
            } else if (o->kind == PUT) {
                nv = o->a;
            } else if (o->kind == DEL) {
                nv = 0;
            } else {
                int hit = val != 0 && val == o->a;
                if (i >= m) nv = hit ? o->b : val;
                else if (o->res) { if (!hit) continue; nv = o->b; }
                else { if (hit) continue; nv = val; }
            }
            cur[i / 64] |= 1ULL << (i % 64);
            uint64_t saved = cur[W];
            cur[W] = (uint64_t)nv;
            size_t ni = intern(cur, &fresh);
            cur[i / 64] &= ~(1ULL << (i % 64));
            cur[W] = saved;
            if (fresh || !fresh) {
                if (sp == scap) { scap *= 2; stack = realloc(stack, sizeof(size_t) * scap); }
                stack[sp++] = ni;
            }
        }
    }
    free(by_call); free(arena); free(table); free(stack); free(cur);
    return ok;
}

int main(void) {
    size_t cap = 1 << 20;
    buf = malloc(cap);
    size_t r;
    while ((r = fread(buf + blen, 1, cap - blen, stdin)) > 0) {
        blen += r;
        if (blen == cap) { cap *= 2; buf = realloc(buf, cap); }
    }
    int T = (int)num();
    for (int t = 0; t < T; t++) {
        int n = (int)num(), k = 0;
        Op *ops = malloc(sizeof(Op) * (size_t)(n ? n : 1));
        for (int i = 0; i < n; i++) {
            Op o; char *s; size_t len;
            memset(&o, 0, sizeof o);
            o.call = num();
            tok(&s, &len);
            int pending = s[0] == '?';
            o.ret = pending ? INF : 0;
            if (!pending) for (size_t q = 0; q < len; q++) o.ret = o.ret * 10 + (s[q] - '0');
            tok(&s, &len);
            o.kind = s[0] == 'G' ? GET : s[0] == 'P' ? PUT : s[0] == 'D' ? DEL : CAS;
            o.key = (int)num();
            if (o.kind == PUT) o.a = num();
            if (o.kind == CAS) { o.a = num(); o.b = num(); }
            if (!pending && o.kind == GET) {
                tok(&s, &len);
                o.res = s[0] == 'N' ? 0 : 0;
                if (s[0] != 'N') for (size_t q = 0; q < len; q++) o.res = o.res * 10 + (s[q] - '0');
            }
            if (!pending && o.kind == CAS) { tok(&s, &len); o.res = s[0] == 'O'; }
            if (pending && o.kind == GET) continue; /* constrains nothing */
            ops[k++] = o;
        }
        qsort(ops, (size_t)k, sizeof(Op), cmp_key);
        int ok = 1;
        for (int i = 0; i < k && ok;) {
            int j = i;
            while (j < k && ops[j].key == ops[i].key) j++;
            ok = check_key(ops + i, j - i);
            i = j;
        }
        puts(ok ? "LINEARIZABLE" : "VIOLATION");
        free(ops);
    }
    return 0;
}
